@startuml

class Museum {
  + name : string
}

class Location {
  + name : string
}

class Exhibition {
  + openingDate : date
}

class Employee {
  + name : string
}

class ExhibitionItem {
  + description : string
}

class Piece {
  + description : string
}

class Collector {
  + name : string
}

class ExhibitionItemRequest {
}

Museum "1" -- "*" Location
Location "1" -- "*" Exhibition
Exhibition "*" -- "1" Employee : coordinator
Exhibition "1" -- "*" ExhibitionItem
ExhibitionItem "1" -- "*" ExhibitionItemRequest
ExhibitionItemRequest "*" -- "1" Piece
ExhibitionItemRequest "*" -- "1" Collector

Employee "0..1" -- "0..*" Employee : coach
@enduml

